local _, FP = ...
local DE = {}
FP.Disenchant = DE

-- Disenchanting: which items can be disenchanted, what they give, what that is worth, and where they are.
-- The loot data is Data/Disenchant.lua, generated by tools/gen_disenchant.py.

DE.SPELL = 13262 -- Disenchant

local band, rshift = bit.band, bit.rshift

---------------------------------------------------------------------------
-- Loot
---------------------------------------------------------------------------
local parsed = {} -- [table id] = { { itemID, chance (0-1), min, max }, ... }

-- A loot table's results. A table can hold several groups that each roll once, so the chances need not add up to 1;
-- each is the chance of getting that result from one disenchant.
function DE:Results(tableID)
    local list = parsed[tableID]
    if not list then
        list = {}
        for item, pct, lo, hi in FP.DisenchantTables[tableID]:gmatch("(%d+),([%d.]+),(%d+),(%d+)") do
            list[#list + 1] = { itemID = tonumber(item), chance = tonumber(pct) / 100, min = tonumber(lo), max = tonumber(hi) }
        end
        parsed[tableID] = list
    end
    return list
end

-- The loot table of a weapon (class 2) or armour (class 4) of uncommon or better quality at its item level; nil when
-- it can't be disenchanted.
function DE:TableFor(itemID, classID, quality, level)
    if FP.DisenchantNever:find("," .. itemID .. ",", 1, true) then return end
    return FP.DisenchantOverride[itemID] or self:BracketTable(classID, quality, level)
end

-- The loot table the level brackets give weapons or armour of this quality and item level, leaving out items with a
-- table of their own; nil when there is none.
function DE:BracketTable(classID, quality, level)
    local byQuality = FP.DisenchantBrackets[classID]
    for _, b in ipairs(byQuality and byQuality[quality] or {}) do
        if level >= b[1] and level <= b[2] then return b[3] end
    end
end

-- What one disenchant of the table is expected to be worth at Auctionator's prices: the sum of each result's chance
-- times its average amount times its price. Also returns how many results have no price (those count as nothing).
function DE:ExpectedValue(tableID)
    local total, unpriced = 0, 0
    for _, r in ipairs(self:Results(tableID)) do
        local unit = FP.Prices:Unit(r.itemID)
        if unit then total = total + r.chance * (r.min + r.max) / 2 * unit
        else unpriced = unpriced + 1 end
    end
    return total, unpriced
end

-- What an item is worth each way, in copper, after the standard auction house cut where it is sold there:
-- vendor, disenchant (the expected results at auction), auction (the item itself; nil when bound or unpriced).
-- best is "vendor", "disenchant" or "auction". Without prices only the vendor value is known. `link` is the item's own
-- link, for its own auction price (see Prices:Unit).
function DE:Values(tableID, sellPrice, itemID, bound, link)
    local P = FP.Prices
    local v = { vendor = sellPrice }
    if P:Available() then
        local gross, unpriced = self:ExpectedValue(tableID)
        v.deGross, v.unpriced = gross, unpriced
        v.disenchant = gross * (1 - P.CUT)
        local unit = not bound and P:Unit(itemID, link)
        if unit then v.auctionGross, v.auction = unit, unit * (1 - P.CUT) end
    end
    v.best, v.bestValue = "vendor", v.vendor
    if v.disenchant and v.disenchant > v.bestValue then v.best, v.bestValue = "disenchant", v.disenchant end
    if v.auction and v.auction > v.bestValue then v.best, v.bestValue = "auction", v.auction end
    return v
end

---------------------------------------------------------------------------
-- Equipment sets
---------------------------------------------------------------------------
-- C_EquipmentSet.GetItemLocations packs where each piece is: flags for the player, their bags and their bank, then
-- the bag in bits 8-15 and the slot in bits 0-7. A piece in a bank tab has both the bags and the bank flag, and its
-- bag counted from 1 for the first bank tab: 6291723 = 0x60010B = bank + bags, tab 1, slot 11 (seen in game
-- 2026-11-13). Forever's tabs are containers of their own, so the tab number is counted from
-- Enum.BagIndex.CharacterBankTab_1, the same containers Inv:BankContainers reads. The game only reports bank pieces
-- while the bank is open; Inv:ScanBank saves their set names with the bank's gear for when it is closed.
local LOC_BAGS, LOC_BANK = ITEM_INVENTORY_LOCATION_BAGS, ITEM_INVENTORY_LOCATION_BANK

local function Key(bag, slot) return bag * 1000 + slot end

-- [Key(bag, slot)] = { set name, ... } for every set piece sitting in a bag or the bank. Worn pieces are left out.
local function SetPieces()
    local pieces = {}
    local E = C_EquipmentSet
    for _, setID in ipairs(E.GetEquipmentSetIDs()) do
        local name = E.GetEquipmentSetInfo(setID)
        for _, loc in pairs(E.GetItemLocations(setID) or {}) do
            -- 1 is an ignored slot, 0 an empty one, -1 a missing item.
            if loc > 1 then
                if band(loc, LOC_BAGS) ~= 0 then
                    local low = band(loc, 0xFFFF)
                    local bag, slot = rshift(low, 8), band(low, 0xFF)
                    if band(loc, LOC_BANK) ~= 0 then bag = Enum.BagIndex.CharacterBankTab_1 + bag - 1 end
                    local k = Key(bag, slot)
                    pieces[k] = pieces[k] or {}
                    table.insert(pieces[k], name)
                end
            end
        end
    end
    return pieces
end

-- The set names of each piece in the open bank, for Inv:ScanBank to save with the bank's gear: while the bank is
-- closed the game reports no location for the pieces in it. Returns a lookup: fn(bag, slot) -> { names } or nil.
function DE:SetLookup()
    local pieces = SetPieces()
    return function(bag, slot) return pieces[Key(bag, slot)] end
end

-- The saved set names that still belong to an equipment set (one may have been deleted since the bank visit).
local function StillSets(names)
    if not names then return end
    local exists, out = {}, {}
    for _, setID in ipairs(C_EquipmentSet.GetEquipmentSetIDs()) do exists[C_EquipmentSet.GetEquipmentSetInfo(setID)] = true end
    for _, name in ipairs(names) do
        if exists[name] then out[#out + 1] = name end
    end
    return #out > 0 and out or nil
end

---------------------------------------------------------------------------
-- Scan
---------------------------------------------------------------------------
-- Disenchantable items in the carried bags and the bank, never what is worn. The bank is read live while it is open,
-- otherwise from the gear saved at the last visit (Inv:ScanBank). Each:
-- { bag, slot, guid, itemID, link, name, icon, quality, level, sellPrice, bound, inBank, tableID, sets = { names } or nil }
-- guid is the item's own GUID, which follows it when it moves to another slot (nil for bank gear saved before it was kept).
-- The list entry for an item link, { itemID, link, name, icon, quality, level, sellPrice, tableID }, or nil when it
-- can't be disenchanted. Also nil while the game hasn't loaded the item; it is asked for, and GET_ITEM_INFO_RECEIVED
-- follows once it has.
local function Entry(link)
    local name, _, quality, level, _, _, _, _, _, icon, sellPrice, classID = C_Item.GetItemInfo(link)
    if not name then
        C_Item.RequestLoadItemDataByID(link)
        return
    end
    if quality < 2 then return end
    local itemID = C_Item.GetItemInfoInstant(link)
    local tableID = DE:TableFor(itemID, classID, quality, level)
    if not tableID then return end
    return { itemID = itemID, link = link, name = name, icon = icon, quality = quality, level = level,
        sellPrice = sellPrice or 0, tableID = tableID }
end

function DE:Scan()
    local out, sets = {}, SetPieces()
    -- `saved`: the set names saved with a closed bank's gear, used in place of the live lookup.
    local function Add(bag, slot, link, bound, inBank, guid, saved)
        local e = Entry(link)
        if not e then return end
        e.bag, e.slot, e.guid, e.bound, e.inBank = bag, slot, guid, bound and true or false, inBank
        e.sets = saved and StillSets(saved) or sets[Key(bag, slot)]
        out[#out + 1] = e
    end
    local function AddSlots(bags, inBank)
        for _, bag in ipairs(bags) do
            for slot = 1, C_Container.GetContainerNumSlots(bag) do
                local info = C_Container.GetContainerItemInfo(bag, slot)
                if info and info.hyperlink then
                    Add(bag, slot, info.hyperlink, info.isBound, inBank, C_Item.GetItemGUID(ItemLocation:CreateFromBagAndSlot(bag, slot)))
                end
            end
        end
    end
    AddSlots(FP.Inv:CarriedBags(), false)
    if FP.Inv.bankOpen then
        AddSlots(FP.Inv:BankContainers(), true)
    else
        for _, g in ipairs(FP.chardb.bankGear or {}) do Add(g.bag, g.slot, g.link, g.bound, true, g.guid, g.sets) end
    end
    return out
end

-- The disenchantable gear your other characters could mail to this one: their unbound gear as last saved
-- (Alts:Gear), from the characters that may supply materials (same faction, not turned off on the Alt Inventory
-- page), in name order. Each is an entry as above without bag or slot (it can't be acted on from here), plus
-- owner (the character's key) and inBank; bound is always false. Items from Syndicator have no GUID, so they get `id`
-- instead: owner, link and how many of that link came before it on that character.
function DE:ScanOthers()
    local out, Alts = {}, FP.Alts
    for _, key in ipairs(Alts:Eligible()) do
        local seen = {}
        local bags, bank = Alts:Gear(key)
        for _, part in ipairs({ { bags, false }, { bank, true } }) do
            for _, g in ipairs(part[1]) do
                local e = Entry(g.link)
                if e then
                    e.owner, e.inBank, e.bound, e.guid = key, part[2], false, g.guid
                    if not g.guid then
                        seen[g.link] = (seen[g.link] or 0) + 1
                        e.id = key .. ":" .. g.link .. ":" .. seen[g.link]
                    end
                    out[#out + 1] = e
                end
            end
        end
    end
    return out
end
